const int low = 70;
const int high = 180;

auto t = id(sys_time).now();
int64_t now = t.is_valid() ? (int64_t) t.timestamp : 0;
int value = id(history)[7];
bool has_data = value > 0 && id(last_ts) > 0;
int64_t age = (has_data && now > 0) ? now - id(last_ts) : -1;
bool stale = has_data && age > 3 * id(period);
bool live = has_data && !stale;

// Zone: -1 low, 0 in range, 1 high
int zone = value < low ? -1 : value > high ? 1 : 0;
const uint32_t GREY = 0x6B7280;
uint32_t zone_color = !live ? GREY : zone < 0 ? 0xF2545B : zone > 0 ? 0xF5B83D : 0x4ADE80;
// Night mode (tap): black background and the zone color moves to a ring around the face
bool night = id(inverted);
uint32_t bg_color = night ? 0x000000 : zone_color;
uint32_t face_color = night ? zone_color : 0xFFFFFF;
const uint32_t INK = night ? 0xE5E7EB : 0x1F2937;

auto set_text = [](lv_obj_t *obj, const std::string &txt) {
  if (txt != lv_label_get_text(obj)) lv_label_set_text(obj, txt.c_str());
};
auto set_ink = [](lv_obj_t *obj, uint32_t c) {
  lv_color_t next = lv_color_hex(c);
  if (!lv_color_eq(lv_obj_get_style_text_color(obj, LV_PART_MAIN), next)) lv_obj_set_style_text_color(obj, next, 0);
};
auto set_fill = [](lv_obj_t *obj, uint32_t c) {
  lv_color_t next = lv_color_hex(c);
  if (!lv_color_eq(lv_obj_get_style_bg_color(obj, LV_PART_MAIN), next)) lv_obj_set_style_bg_color(obj, next, 0);
};
auto set_hidden = [](lv_obj_t *obj, bool hide) {
  if (hide == lv_obj_has_flag(obj, LV_OBJ_FLAG_HIDDEN)) return;
  if (hide) lv_obj_add_flag(obj, LV_OBJ_FLAG_HIDDEN);
  else lv_obj_remove_flag(obj, LV_OBJ_FLAG_HIDDEN);
};
auto set_box = [](lv_obj_t *obj, int x, int y, int w, int h) {
  if (lv_obj_get_x(obj) != x) lv_obj_set_x(obj, x);
  if (lv_obj_get_y(obj) != y) lv_obj_set_y(obj, y);
  if (lv_obj_get_style_width(obj, LV_PART_MAIN) != w) lv_obj_set_width(obj, w);
  if (lv_obj_get_style_height(obj, LV_PART_MAIN) != h) lv_obj_set_height(obj, h);
};
auto format = [](const char *fmt, int n) {
  char buf[64];
  snprintf(buf, sizeof(buf), fmt, n);
  return std::string(buf);
};

set_fill(id(bg), bg_color);
// Day: white disc. Night: black disc with a ring in the zone color (a yellow
// disc would swallow the yellow emoji).
lv_obj_t *fc = (lv_obj_t *) id(face);
set_fill(fc, night ? 0x000000 : 0xFFFFFF);
int ring = night ? 14 : 0;
// At night the disc shrinks so the ring hugs the emoji (visible face ~140 px of
// the 156 px image): inner diameter 136, the emoji edge covers the seam.
int disc = night ? 136 + 2 * ring : 200;
set_box(fc, 204 - disc / 2, 156 - disc / 2, disc, disc);
if (lv_obj_get_style_border_width(fc, LV_PART_MAIN) != ring) lv_obj_set_style_border_width(fc, ring, 0);
if (!lv_color_eq(lv_obj_get_style_border_color(fc, LV_PART_MAIN), lv_color_hex(face_color)))
  lv_obj_set_style_border_color(fc, lv_color_hex(face_color), 0);
lv_obj_t *gg = (lv_obj_t *) id(gauge);
if (!lv_color_eq(lv_obj_get_style_border_color(gg, LV_PART_MAIN), lv_color_hex(INK)))
  lv_obj_set_style_border_color(gg, lv_color_hex(INK), 0);
// Without fresh data the gauge fades: it isn't pointing at anything
lv_opa_t gauge_opa = live ? LV_OPA_COVER : LV_OPA_40;
if (lv_obj_get_style_opa(gg, LV_PART_MAIN) != gauge_opa) lv_obj_set_style_opa(gg, gauge_opa, 0);
for (auto *l : {id(lbl_arrow), id(lbl_number), id(lbl_unit), id(lbl_status)})
  set_ink((lv_obj_t *) l, INK);

// Gauge marker: piecewise scale so each band has a readable size.
// 40-70 -> bottom 64 px, 70-180 -> middle 124 px, 180-300 -> top 84 px (gauge inner height 272).
lv_obj_t *mk = (lv_obj_t *) id(marker);
set_hidden(mk, !live);
if (live) {
  int v = std::max(40, std::min(300, value));
  int from_bottom;
  if (v < low) from_bottom = (v - 40) * 64 / (low - 40);
  else if (v <= high) from_bottom = 64 + (v - low) * 124 / (high - low);
  else from_bottom = 188 + (v - high) * 84 / (300 - high);
  int y = 24 + 272 - from_bottom - 14;
  set_box(mk, 12, y, 64, 28);
}

static const char *ARROWS[] = {
  "\U000F0374", "\U000F013F", "\U000F005D", "\U000F005C", "\U000F0054",
  "\U000F0043", "\U000F0045", "\U000F013C", "\U000F02D6", "\U000F0374",
};
int tr = id(trend);
if (tr < 0 || tr > 9) tr = 0;

// Face: smiling in range, "oh" when low, neutral when high, asleep without fresh data
auto *emoji = !live ? id(emoji_asleep) : zone < 0 ? id(emoji_low) : zone > 0 ? id(emoji_high) : id(emoji_ok);
lv_obj_t *fi = (lv_obj_t *) id(face_img);
if (lv_image_get_src(fi) != emoji->get_lv_image_dsc()) lv_image_set_src(fi, emoji->get_lv_image_dsc());

// Trend arrow
set_text((lv_obj_t *) id(lbl_arrow), live ? ARROWS[tr] : "");

// Number, for grown-ups
set_text((lv_obj_t *) id(lbl_number), has_data ? std::to_string(value) : "");
set_hidden((lv_obj_t *) id(lbl_unit), !has_data);

std::string age_text = "";
if (age >= 0) {
  int min = age / 60;
  if (min >= 1) age_text = format("%d min ago", min);
  else age_text = stale ? format("%d s ago", (int) age) : "now";
}
lv_obj_t *age_lbl = (lv_obj_t *) id(lbl_age);
set_text(age_lbl, age_text);
// Old data: the number fades and the age stands out
lv_opa_t num_opa = stale ? LV_OPA_40 : LV_OPA_COVER;
lv_obj_t *num = (lv_obj_t *) id(lbl_number);
if (lv_obj_get_style_text_opa(num, LV_PART_MAIN) != num_opa) {
  lv_obj_set_style_text_opa(num, num_opa, 0);
  lv_obj_set_style_text_opa((lv_obj_t *) id(lbl_unit), num_opa, 0);
}
lv_opa_t pill = stale ? LV_OPA_COVER : LV_OPA_TRANSP;
if (lv_obj_get_style_bg_opa(age_lbl, LV_PART_MAIN) != pill) lv_obj_set_style_bg_opa(age_lbl, pill, 0);
set_ink(age_lbl, stale ? 0xFFFFFF : INK);

std::string status = id(status_text);
if (status.empty() && stale) status = "No new data";
set_text((lv_obj_t *) id(lbl_status), status);

lv_obj_t *wifi = (lv_obj_t *) id(lbl_wifi);
set_text(wifi, id(connected) ? "\U000F05A9" : "\U000F05AA");
set_ink(wifi, INK);

auto now = id(sys_time).now().timestamp;
std::vector<int> h(8, 0);
if (value > 0) {
  // A smooth made-up history ending in previous -> value
  int step = value - previous;
  for (int i = 0; i < 8; i++) h[i] = std::max(40, value - step * (7 - i));
}
id(history) = h;
id(last_ts) = value > 0 ? now - age_s : 0;
id(delta) = value - previous;
id(delta_ok) = previous > 0;
id(trend) = trend_now;
id(connected) = status.empty();
id(status_text) = status;
